<div class="page-heading"><div><div class="eyebrow">Administrasi</div><h1>Data pemohon</h1><p>Kelola identitas pemohon dan buka riwayat pengajuannya dari satu daftar.</p></div><?php if ($this->metro->can($current_user->id,'applicants.create')): ?><button class="button primary" type="button" data-modal-open="add-applicant">+ Tambah pemohon</button><?php endif; ?></div>
<form class="card filter-card" method="get" action="<?= site_url('petugas/pemohon') ?>"><div class="search-bar" style="margin:0"><input type="search" name="q" value="<?= e($query) ?>" placeholder="Cari nama, email, atau instansi" aria-label="Cari pemohon"><button class="button primary" type="submit">Cari</button></div></form>
<section class="card table-card"><div class="filter-results"><span><strong><?= (int)$pagination['total'] ?></strong> pemohon ditemukan</span><a href="<?= site_url('petugas/pemohon') ?>">Hapus pencarian</a></div>
<?php if ($applicants): ?><div class="table-scroll"><table class="data-table"><thead><tr><th>Nama pemohon</th><th>Instansi</th><th>Kontak</th><th>Permohonan</th><th>Terakhir masuk</th><th>Aksi</th></tr></thead><tbody><?php foreach ($applicants as $person): ?><tr><td data-label="Pemohon"><strong><?= e($person->full_name) ?></strong><small><?= e($person->username ?: '—') ?></small><small><span class="badge <?= $person->account_status==='active'?'success':'danger' ?>"><?= $person->account_status==='active'?'Aktif':($person->account_status==='pending'?'Menunggu':'Nonaktif') ?></span></small></td><td data-label="Instansi"><?= e($person->organization_name ?: '—') ?></td><td data-label="Kontak"><?= email_html($person->email) ?><small><?= e($person->phone) ?> · <?= $person->phone_verified_at?'Terverifikasi':($person->phone_verification_required?'Perlu verifikasi':'Persetujuan manual') ?></small></td><td data-label="Permohonan"><?= (int)$person->request_count ?></td><td data-label="Terakhir"><?= $person->last_submission?e(tanggal_id($person->last_submission)):'—' ?></td><td data-label="Aksi"><div class="row-actions"><a class="action-link" href="<?= site_url('petugas/pemohon/'.$person->id) ?>">Detail</a><?php if ($person->account_status==='pending' && $this->metro->can($current_user->id,'applicants.status')): ?><form method="post" action="<?= site_url('petugas/akun-setujui/'.$person->id) ?>"><?= form_hidden($this->security->get_csrf_token_name(),$this->security->get_csrf_hash()) ?><button class="action-link" type="submit">Setujui</button></form><?php endif; ?><?php if ($this->metro->can($current_user->id,'applicants.update')): ?><button type="button" class="action-link" data-modal-open="edit-applicant-<?= (int)$person->id ?>">Edit</button><?php endif; ?><?php if ($person->account_status==='active' && $this->metro->can($current_user->id,'applicants.update')): ?><form method="post" action="<?= site_url('petugas/akun-kredensial/'.$person->id) ?>" onsubmit="return confirm('Atur ulang kata sandi akun ini?')"><?= form_hidden($this->security->get_csrf_token_name(),$this->security->get_csrf_hash()) ?><button class="action-link" type="submit">Atur ulang akses</button></form><?php endif; ?><?php if ($person->account_status!=='pending' && $this->metro->can($current_user->id,'applicants.status')): ?><form method="post" action="<?= site_url('petugas/pemohon/status/'.$person->id) ?>"><?= form_hidden($this->security->get_csrf_token_name(),$this->security->get_csrf_hash()) ?><button type="submit" class="action-link"><?= $person->account_status==='active'?'Nonaktifkan':'Aktifkan' ?></button></form><?php endif; ?><?php if ($this->metro->can($current_user->id,'applicants.delete')): ?><form method="post" action="<?= site_url('petugas/pemohon/hapus/'.$person->id) ?>" onsubmit="return confirm('Hapus pemohon yang belum memiliki riwayat?')"><?= form_hidden($this->security->get_csrf_token_name(),$this->security->get_csrf_hash()) ?><button type="submit" class="action-link danger">Hapus</button></form><?php endif; ?></div></td></tr><?php endforeach; ?></tbody></table></div><?php else: ?><div class="table-empty"><strong>Belum ada pemohon yang cocok</strong>Coba kata kunci lain.</div><?php endif; ?><?= metro_pager($pagination,'petugas/pemohon',$query?array('q'=>$query):array()) ?></section>
<?php if ($this->metro->can($current_user->id,'applicants.create')): ?><dialog id="add-applicant" class="admin-modal" aria-labelledby="add-applicant-title"><div class="modal-head"><div><small>Akun pemohon</small><h2 id="add-applicant-title">Tambah pemohon</h2></div><button type="button" class="modal-close" data-modal-close aria-label="Tutup">×</button></div><form method="post" action="<?= site_url('petugas/pemohon/tambah') ?>"><?= form_hidden($this->security->get_csrf_token_name(),$this->security->get_csrf_hash()) ?><div class="modal-body"><div class="form-grid"><label>Nama lengkap<input name="full_name" required minlength="3" maxlength="160"></label><label>Username <small>opsional</small><input name="username" pattern="[a-z0-9._-]{4,90}" minlength="4" maxlength="90" autocomplete="off"></label><label>Email<input type="email" name="email" required></label><label>Nomor telepon<input name="phone" type="tel" pattern="08[0-9]{8,12}" required></label><label>Kata sandi awal<input name="password" type="password" required minlength="8" maxlength="72" autocomplete="new-password"></label><label>Jenis pemohon<select name="profile_kind" required><?php foreach ($profile_kinds as $kind): if (!$kind->is_active) continue; ?><option value="<?= e($kind->option_code) ?>"><?= e($kind->option_label) ?></option><?php endforeach; ?></select></label><label>Instansi <small>(opsional)</small><input name="organization_name" maxlength="190"></label><label>Penanggung jawab<input name="contact_person" required minlength="3" maxlength="160"></label><label>Kecamatan<select name="district_id" id="applicant-district-new" required><option value="">Pilih kecamatan</option><?php foreach ($districts as $district): if (!$district->is_active) continue; ?><option value="<?= (int)$district->id ?>"><?= e($district->district_name) ?></option><?php endforeach; ?></select></label><div><div class="field-label">Desa / kelurahan</div><div class="ajax-village" data-url="<?= site_url('api/wilayah/desa') ?>" data-district="applicant-district-new"><input type="hidden" name="village_id"><input class="ajax-village-input" type="search" role="combobox" aria-autocomplete="list" aria-expanded="false" autocomplete="off" placeholder="Cari desa"><div class="ajax-village-results" role="listbox" hidden></div></div></div><label class="span-2">Alamat lengkap<textarea name="address" required minlength="10" rows="3"></textarea></label></div><p class="muted small">Pemohon perlu memverifikasi telepon sebelum mengajukan layanan.</p></div><div class="modal-actions"><button type="button" class="button outline" data-modal-close>Batal</button><button class="button primary" type="submit">Tambah pemohon</button></div></form></dialog>
<?php endif; ?>
<?php if ($this->metro->can($current_user->id,'applicants.update')): foreach ($applicants as $person): $district_element='applicant-district-'.$person->id; ?><dialog id="edit-applicant-<?= (int)$person->id ?>" class="admin-modal" aria-labelledby="edit-applicant-title-<?= (int)$person->id ?>"><div class="modal-head"><div><small>Akun pemohon</small><h2 id="edit-applicant-title-<?= (int)$person->id ?>">Edit <?= e($person->full_name) ?></h2></div><button type="button" class="modal-close" data-modal-close aria-label="Tutup">×</button></div><form method="post" action="<?= site_url('petugas/pemohon/ubah/'.$person->id) ?>"><?= form_hidden($this->security->get_csrf_token_name(),$this->security->get_csrf_hash()) ?><div class="modal-body"><div class="form-grid"><label>Nama lengkap<input name="full_name" required minlength="3" maxlength="160" value="<?= e($person->full_name) ?>"></label><label>Username<input name="username" pattern="[a-z0-9._-]{4,90}" minlength="4" maxlength="90" value="<?= e($person->username) ?>"></label><label>Email<input type="email" name="email" value="<?= e($person->email) ?>" placeholder="Opsional"></label><label>Nomor telepon<input name="phone" type="tel" pattern="08[0-9]{8,12}" value="<?= e($person->phone) ?>" placeholder="Opsional"></label><label>Kata sandi baru <small>(opsional)</small><input name="password" type="password" minlength="8" maxlength="72" autocomplete="new-password" placeholder="Kosongkan bila tidak diubah"></label><label>Jenis pemohon<select name="profile_kind" required><?php foreach ($profile_kinds as $kind): if (!$kind->is_active && $kind->option_code!==$person->profile_kind) continue; ?><option value="<?= e($kind->option_code) ?>"<?= $person->profile_kind===$kind->option_code?' selected':'' ?>><?= e($kind->option_label) ?></option><?php endforeach; ?></select></label><label>Instansi <small>(opsional)</small><input name="organization_name" maxlength="190" value="<?= e($person->organization_name) ?>"></label><label>Penanggung jawab<input name="contact_person" required minlength="3" maxlength="160" value="<?= e($person->contact_person) ?>"></label><label>Kecamatan<select name="district_id" id="<?= e($district_element) ?>" required><option value="">Pilih kecamatan</option><?php foreach ($districts as $district): ?><option value="<?= (int)$district->id ?>"<?= (int)$person->district_id===(int)$district->id?' selected':'' ?>><?= e($district->district_name) ?></option><?php endforeach; ?></select></label><div><div class="field-label">Desa / kelurahan</div><div class="ajax-village" data-url="<?= site_url('api/wilayah/desa') ?>" data-district="<?= e($district_element) ?>"><input type="hidden" name="village_id" value="<?= $person->village_id?(int)$person->village_id:'' ?>"><input class="ajax-village-input" type="search" role="combobox" aria-autocomplete="list" aria-expanded="false" autocomplete="off" placeholder="Cari desa" value="<?= e($person->village_name ?: '') ?>"><div class="ajax-village-results" role="listbox" hidden></div></div></div><label class="span-2">Alamat lengkap<textarea name="address" required minlength="10" rows="3"><?= e($person->address) ?></textarea></label></div></div><div class="modal-actions"><button type="button" class="button outline" data-modal-close>Batal</button><button class="button primary" type="submit">Simpan perubahan</button></div></form></dialog><?php endforeach; endif; ?>
